const data = $('Source 1').first().json;

// Initialize band summary object
const bands = {
  minor: { event_count: 0, max_magnitude: -Infinity, max_depth_km: -Infinity },
  moderate: { event_count: 0, max_magnitude: -Infinity, max_depth_km: -Infinity },
  major: { event_count: 0, max_magnitude: -Infinity, max_depth_km: -Infinity }
};

// Process each earthquake feature
for (const feature of data.features) {
  const mag = feature.properties.mag;
  const depth = feature.geometry.coordinates[2];

  let band;
  if (mag < 4.0) {
    band = 'minor';
  } else if (mag >= 4.0 && mag < 5.0) {
    band = 'moderate';
  } else {
    band = 'major';
  }

  // Update band stats
  bands[band].event_count++;
  if (mag > bands[band].max_magnitude) {
    bands[band].max_magnitude = mag;
  }
  if (depth > bands[band].max_depth_km) {
    bands[band].max_depth_km = depth;
  }
}

// Build final records array with only bands that have events
const records = [];
for (const [band, stats] of Object.entries(bands)) {
  if (stats.event_count > 0) {
    records.push({
      magnitude_band: band,
      event_count: stats.event_count,
      max_magnitude: stats.max_magnitude,
      max_depth_km: stats.max_depth_km
    });
  }
}

return [{ json: { records } }];
